const MIN_NEIGHBORS_TO_SURVIVE = 2;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const everyCellIsUnderpopulated =
    liveCells.length <= MIN_NEIGHBORS_TO_SURVIVE;

  if (everyCellIsUnderpopulated) return [];

  return liveCells;
}
